function uniqueOnly(head: ListNode | null): ListNode | null {
  const count = new Map<number, number>();
  for (let p = head; p; p = p.next) count.set(p.val, (count.get(p.val) ?? 0) + 1);
  const dummy = new ListNode(0);
  let tail = dummy;
  for (let p = head; p; p = p.next) {
    if (count.get(p.val) === 1) { tail.next = new ListNode(p.val); tail = tail.next; }
  }
  return dummy.next;
}

